  1	### packages/contracts/src/interfaces/IRaffleFactory.sol
  2	// SPDX-License-Identifier: MIT
  3	pragma solidity 0.8.36;
  4	
  5	/// @title raffle.fun Raffle Factory Interface
  6	/// @author heesho
  7	/// @notice Defines atomic ERC-1167 raffle creation for one immutable USDC, treasury, and Chainlink configuration.
  8	/// @dev The factory has no owner, pause, upgrade, rescue, or mutable protocol configuration. Deployment tooling must
  9	///      verify that the immutable quote-token address is the target chain's official USDC; onchain construction checks
 10	///      only code presence and six-decimal metadata.
 11	/// @custom:version 1.0.0
 12	interface IRaffleFactory {
 13	    // Types
 14	
 15	    /// @notice Sponsor-selected configuration for one new raffle.
 16	    /// @param sponsorRecipient Immutable recipient of sponsor quote proceeds and any returned prize.
 17	    /// @param prizeToken Standards-compliant ERC-721 prize contract.
 18	    /// @param prizeTokenId Token ID to escrow atomically during creation.
 19	    /// @param reserveEntries Global raw entry-count threshold selecting the NFT outcome when met or exceeded.
 20	    /// @param endTime Exclusive sale-end Unix timestamp, in seconds.
 21	    struct CreateRaffleParams {
 22	        address sponsorRecipient;
 23	        address prizeToken;
 24	        uint256 prizeTokenId;
 25	        uint128 reserveEntries;
 26	        uint64 endTime;
 27	    }
 28	
 29	    // Events
 30	
 31	    /// @notice Emitted after a raffle clone is initialized, registered, funded, and active.
 32	    /// @param raffleId One-based canonical raffle identifier.
 33	    /// @param raffle Newly created fixed-target ERC-1167 clone.
 34	    /// @param sponsor Prize depositor and pre-end empty-raffle refund authority.
 35	    /// @param sponsorRecipient Immutable recipient of sponsor quote proceeds and any returned prize.
 36	    /// @param prizeToken ERC-721 contract of the escrowed prize.
 37	    /// @param prizeTokenId Token ID of the escrowed prize.
 38	    /// @param quoteToken Immutable canonical six-decimal USDC contract used by the raffle.
 39	    /// @param protocolTreasury Immutable recipient of protocol fees.
 40	    /// @param reserveEntries Global raw entry-count threshold selecting the NFT outcome when met or exceeded.
 41	    /// @param endTime Exclusive sale-end Unix timestamp, in seconds.
 42	    event RaffleCreated(
 43	        uint256 indexed raffleId,
 44	        address indexed raffle,
 45	        address indexed sponsor,
 46	        address sponsorRecipient,
 47	        address prizeToken,
 48	        uint256 prizeTokenId,
 49	        address quoteToken,
 50	        address protocolTreasury,
 51	        uint128 reserveEntries,
 52	        uint64 endTime
 53	    );
 54	
 55	    // Errors
 56	
 57	    /// @notice Raised when a required address is the zero address.
 58	    error ZeroAddress();
 59	
 60	    /// @notice Raised when an address required to contain deployed code is not a contract.
 61	    /// @param account Address whose code length was zero.
 62	    error NotContract(address account);
 63	
 64	    /// @notice Raised when the quote token cannot report its decimal precision.
 65	    /// @param quoteToken Rejected quote-token contract.
 66	    error UnsupportedQuoteToken(address quoteToken);
 67	
 68	    /// @notice Raised when the quote token does not use the required six-decimal precision.
 69	    /// @param actualDecimals Decimal precision reported by the quote token.
 70	    /// @param requiredDecimals Required decimal precision, exactly six.
 71	    error InvalidQuoteTokenDecimals(uint8 actualDecimals, uint8 requiredDecimals);
 72	
 73	    /// @notice Raised when the prize contract does not report ERC-721 interface support.
 74	    /// @param prizeToken Rejected prize-token contract.
 75	    error UnsupportedPrizeToken(address prizeToken);
 76	
 77	    /// @notice Raised when a raffle is configured with a zero reserve entry threshold.
 78	    error ZeroReserveEntries();
 79	
 80	    /// @notice Raised when the sale end is not strictly after the creation block timestamp.
 81	    /// @param currentTime Current block Unix timestamp, in seconds.
 82	    /// @param endTime Supplied exclusive sale-end Unix timestamp, in seconds.
 83	    error InvalidEndTime(uint256 currentTime, uint256 endTime);
 84	
 85	    /// @notice Raised when the prospective sale duration exceeds the fixed 30-day limit.
 86	    /// @param duration Prospective sale duration in seconds.
 87	    /// @param maximumDuration Maximum permitted sale duration in seconds.
 88	    error SaleDurationTooLong(uint256 duration, uint256 maximumDuration);
 89	
 90	    /// @notice Raised when a configured token or recipient is known protocol plumbing.
 91	    /// @param destination Rejected address.
 92	    error UnsafeProtocolDestination(address destination);
 93	
 94	    /// @notice Raised when the exact configured prize is not owned by an active clone after escrow.
 95	    /// @param raffle Newly created clone expected to hold the prize and report `Active`.
 96	    /// @param prizeToken ERC-721 prize contract.
 97	    /// @param prizeTokenId Configured prize token ID.
 98	    error PrizeEscrowVerificationFailed(address raffle, address prizeToken, uint256 prizeTokenId);
 99	
100	    // External state-changing functions
101	
102	    /// @notice Creates, initializes, registers, and funds one autonomous fixed-target raffle clone atomically.
103	    /// @param params Sponsor-selected recipient, prize, reserve, and timing configuration.
104	    /// @return raffle Address of the newly created and activated clone.
105	    function createRaffle(CreateRaffleParams calldata params) external returns (address raffle);
106	
107	    // Public generated getters
108	
109	    /// @notice Returns the immutable canonical six-decimal USDC contract used by every raffle.
110	    /// @return quoteTokenAddress Canonical USDC contract address trusted by this deployment.
111	    function quoteToken() external view returns (address quoteTokenAddress);
112	
113	    /// @notice Returns the immutable Chainlink VRF v2.5 native direct-funding wrapper used by every raffle.
114	    /// @return wrapperAddress Wrapper contract address.
115	    function vrfWrapper() external view returns (address wrapperAddress);
116	
117	    /// @notice Returns the immutable recipient of protocol fees from every raffle.
118	    /// @return treasuryAddress Protocol treasury address.
119	    function protocolTreasury() external view returns (address treasuryAddress);
120	
121	    /// @notice Returns the fixed Chainlink callback execution limit used by every raffle.
122	    /// @return gasLimit Callback gas units requested from the wrapper.
123	    function callbackGasLimit() external view returns (uint32 gasLimit);
124	
125	    /// @notice Returns the fixed Chainlink confirmation count used by every raffle.
126	    /// @return confirmations Blocks requested before callback fulfillment.
127	    function requestConfirmations() external view returns (uint16 confirmations);
128	
129	    /// @notice Returns the immutable implementation targeted by every registered ERC-1167 clone.
130	    /// @return implementation Locked raffle implementation address.
131	    function raffleImplementation() external view returns (address implementation);
132	
133	    /// @notice Returns the lifetime number of successfully created raffles.
134	    /// @return count Latest one-based raffle identifier and total registered raffle count.
135	    function raffleCount() external view returns (uint256 count);
136	
137	    /// @notice Returns whether an address is a raffle registered by this factory.
138	    /// @param raffle Address to check.
139	    /// @return registered True only for a successfully created canonical clone.
140	    function isRaffle(address raffle) external view returns (bool registered);
141	
142	    /// @notice Returns the canonical raffle address for an identifier.
143	    /// @param raffleId One-based raffle identifier.
144	    /// @return raffle Registered clone address, or the zero address for an unknown identifier.
145	    function raffleById(uint256 raffleId) external view returns (address raffle);
146	
147	    /// @notice Returns the canonical identifier assigned to a raffle address.
148	    /// @param raffle Address to query.
149	    /// @return raffleId One-based identifier, or zero for an unregistered address.
150	    function idByRaffle(address raffle) external view returns (uint256 raffleId);
151	}
