153	### packages/contracts/src/libraries/RaffleConstants.sol
154	// SPDX-License-Identifier: MIT
155	pragma solidity 0.8.36;
156	
157	/// @title raffle.fun Protocol Constants
158	/// @author heesho
159	/// @notice Defines the fixed v1 economics, timing, and bounded-execution limits shared by the factory and raffles.
160	/// @dev Quote-token amounts use raw six-decimal units. Basis-point calculations round down through `Math.mulDiv`, and
161	///      the sponsor receives the remaining raw units after winner and protocol allocations.
162	/// @custom:version 1.0.0
163	library RaffleConstants {
164	    /// @notice Denominator used for every global protocol basis-point rate.
165	    uint256 internal constant BPS = 10_000;
166	
167	    /// @notice Global protocol fee rate: 500 basis points, or 5% of gross sales.
168	    uint256 internal constant PROTOCOL_FEE_BPS = 500;
169	
170	    /// @notice Cash-result winner rate: 8,000 basis points, or 80% of gross sales.
171	    uint256 internal constant CASH_WINNER_BPS = 8000;
172	
173	    /// @notice Global entry price: exactly 1,000,000 raw six-decimal quote-token units, or one USDC.
174	    uint256 internal constant ENTRY_PRICE = 1_000_000;
175	
176	    /// @notice Decimal precision required from the immutable quote token.
177	    uint8 internal constant QUOTE_TOKEN_DECIMALS = 6;
178	
179	    /// @notice Refund execution is bounded by tickets, while each ticket may represent any uint128 entry count.
180	    uint256 internal constant MAX_REFUND_TICKET_BATCH_SIZE = 100;
181	
182	    /// @notice Maximum prospective raffle sale duration, measured from creation to the exclusive sale end.
183	    uint256 internal constant MAX_SALE_DURATION = 30 days;
184	
185	    /// @notice Duration after sale end during which a sold raffle may initiate its draw, in seconds.
186	    uint256 internal constant DRAW_REQUEST_TIMEOUT = 2 days;
187	
188	    /// @notice Duration after an accepted request during which its authenticated callback may resolve, in seconds.
189	    uint256 internal constant DRAW_CALLBACK_TIMEOUT = 2 days;
190	
191	    /// @notice Gas-unit limit requested for the single-word Chainlink callback.
192	    uint32 internal constant VRF_CALLBACK_GAS_LIMIT = 300_000;
193	
194	    /// @notice Block confirmations requested from Chainlink before callback fulfillment.
195	    uint16 internal constant VRF_REQUEST_CONFIRMATIONS = 30;
196	}
