213	/// @title raffle.fun Canonical USDC Raffle Factory
214	/// @author heesho
215	/// @notice Atomically creates, funds, and registers autonomous fixed-implementation raffle clones.
216	/// @dev The implementation, canonical six-decimal USDC, treasury, fee, and Chainlink configuration are immutable. The
217	///      factory has no owner, pause, upgrade, rescue, or mutable protocol configuration.
218	/// @custom:version 1.0.0
219	contract RaffleFactory is IRaffleFactory, ReentrancyGuard {
220	    // Constants
221	
222	    /// @inheritdoc IRaffleFactory
223	    uint32 public constant override callbackGasLimit = RaffleConstants.VRF_CALLBACK_GAS_LIMIT;
224	
225	    /// @inheritdoc IRaffleFactory
226	    uint16 public constant override requestConfirmations = RaffleConstants.VRF_REQUEST_CONFIRMATIONS;
227	
228	    // Immutables and state
229	
230	    /// @inheritdoc IRaffleFactory
231	    address public immutable override quoteToken;
232	
233	    /// @inheritdoc IRaffleFactory
234	    address public immutable override vrfWrapper;
235	
236	    /// @inheritdoc IRaffleFactory
237	    address public immutable override protocolTreasury;
238	
239	    /// @inheritdoc IRaffleFactory
240	    address public immutable override raffleImplementation;
241	
242	    /// @inheritdoc IRaffleFactory
243	    uint256 public override raffleCount;
244	
245	    /// @inheritdoc IRaffleFactory
246	    mapping(uint256 raffleId => address raffle) public override raffleById;
247	
248	    /// @inheritdoc IRaffleFactory
249	    mapping(address raffle => uint256 raffleId) public override idByRaffle;
250	
251	    /// @inheritdoc IRaffleFactory
252	    mapping(address raffle => bool registered) public override isRaffle;
253	
254	    // Constructor
255	
256	    /// @notice Deploys the ownerless factory and its locked raffle implementation with one immutable configuration.
257	    /// @dev The quote token must report exactly six decimals; the wrapper and quote token must contain deployed code.
258	    ///      Deployment tooling must supply and verify the target chain's official USDC address because the constructor
259	    ///      cannot prove token identity from metadata.
260	    /// @param quoteToken_ Target chain's official six-decimal USDC contract trusted by every raffle.
261	    /// @param vrfWrapper_ Official Chainlink VRF v2.5 native direct-funding wrapper for the target chain.
262	    /// @param protocolTreasury_ Immutable protocol-fee recipient used by every raffle.
263	    constructor(address quoteToken_, address vrfWrapper_, address protocolTreasury_) {
264	        _requireContract(quoteToken_);
265	        _requireContract(vrfWrapper_);
266	        if (protocolTreasury_ == address(0)) revert ZeroAddress();
267	
268	        uint8 quoteDecimals = 0;
269	        try IERC20Metadata(quoteToken_).decimals() returns (uint8 decimals_) {
270	            quoteDecimals = decimals_;
271	        } catch {
272	            revert UnsupportedQuoteToken(quoteToken_);
273	        }
274	        if (quoteDecimals != RaffleConstants.QUOTE_TOKEN_DECIMALS) {
275	            revert InvalidQuoteTokenDecimals(quoteDecimals, RaffleConstants.QUOTE_TOKEN_DECIMALS);
276	        }
277	
278	        if (protocolTreasury_ == address(this) || protocolTreasury_ == quoteToken_ || protocolTreasury_ == vrfWrapper_)
279	        {
280	            revert UnsafeProtocolDestination(protocolTreasury_);
281	        }
282	
283	        quoteToken = quoteToken_;
284	        vrfWrapper = vrfWrapper_;
285	        protocolTreasury = protocolTreasury_;
286	
287	        address implementation = address(new Raffle(quoteToken_, vrfWrapper_));
288	        if (protocolTreasury_ == implementation) revert UnsafeProtocolDestination(protocolTreasury_);
289	        raffleImplementation = implementation;
290	    }
291	
292	    // External state-changing functions
293	
294	    /// @inheritdoc IRaffleFactory
295	    function createRaffle(CreateRaffleParams calldata params) external override nonReentrant returns (address raffle) {
296	        _validateCreateParams(params);
297	        uint256 currentTime = block.timestamp;
298	        if (params.endTime <= currentTime) revert InvalidEndTime(currentTime, params.endTime);
299	        uint256 saleDuration = uint256(params.endTime) - currentTime;
300	        if (saleDuration > RaffleConstants.MAX_SALE_DURATION) {
301	            revert SaleDurationTooLong(saleDuration, RaffleConstants.MAX_SALE_DURATION);
302	        }
303	        uint256 raffleId = ++raffleCount;
304	        raffle = Clones.clone(raffleImplementation);
305	        // The fresh fixed-target clone can initialize only once; this function is nonReentrant and atomic.
306	        // slither-disable-next-line reentrancy-no-eth
307	        IRaffle(raffle)
308	            .initialize(
309	                IRaffle.RaffleInitParams({
310	                sponsor: msg.sender,
311	                sponsorRecipient: params.sponsorRecipient,
312	                protocolTreasury: protocolTreasury,
313	                prizeToken: params.prizeToken,
314	                prizeTokenId: params.prizeTokenId,
315	                raffleId: raffleId,
316	                reserveEntries: params.reserveEntries,
317	                endTime: params.endTime
318	            })
319	            );
320	
321	        raffleById[raffleId] = raffle;
322	        idByRaffle[raffle] = raffleId;
323	        isRaffle[raffle] = true;
324	
325	        IERC721 prize = IERC721(params.prizeToken);
326	        prize.safeTransferFrom(msg.sender, raffle, params.prizeTokenId);
327	        if (prize.ownerOf(params.prizeTokenId) != raffle) {
328	            revert PrizeEscrowVerificationFailed(raffle, params.prizeToken, params.prizeTokenId);
329	        }
330	        if (IRaffle(raffle).status() != IRaffle.Status.Active) {
331	            revert PrizeEscrowVerificationFailed(raffle, params.prizeToken, params.prizeTokenId);
332	        }
333	
334	        emit RaffleCreated(
335	            raffleId,
336	            raffle,
337	            msg.sender,
338	            params.sponsorRecipient,
339	            params.prizeToken,
340	            params.prizeTokenId,
341	            quoteToken,
342	            protocolTreasury,
343	            params.reserveEntries,
344	            params.endTime
345	        );
346	    }
347	
348	    // Private view helpers
349	
350	    /// @dev Validates the sponsor-selected token, recipient, reserve, and supported ERC-721 interface before cloning.
351	    /// @param params Prospective raffle configuration supplied by the sponsor.
352	    function _validateCreateParams(CreateRaffleParams calldata params) private view {
353	        _requireContract(params.prizeToken);
354	        if (params.sponsorRecipient == address(0)) revert ZeroAddress();
355	        if (
356	            params.prizeToken == address(this) || params.prizeToken == quoteToken || params.prizeToken == vrfWrapper
357	                || params.prizeToken == raffleImplementation || isRaffle[params.prizeToken]
358	        ) {
359	            revert UnsafeProtocolDestination(params.prizeToken);
360	        }
361	        if (
362	            params.sponsorRecipient == address(this) || params.sponsorRecipient == quoteToken
363	                || params.sponsorRecipient == vrfWrapper || params.sponsorRecipient == params.prizeToken
364	                || params.sponsorRecipient == raffleImplementation || isRaffle[params.sponsorRecipient]
365	        ) {
366	            revert UnsafeProtocolDestination(params.sponsorRecipient);
367	        }
368	
369	        bool supports721 = false;
370	        try IERC165(params.prizeToken).supportsInterface(type(IERC721).interfaceId) returns (bool supported) {
371	            supports721 = supported;
372	        } catch {
373	            revert UnsupportedPrizeToken(params.prizeToken);
374	        }
375	        if (!supports721) revert UnsupportedPrizeToken(params.prizeToken);
376	        if (params.reserveEntries == 0) revert ZeroReserveEntries();
377	    }
378	
379	    /// @dev Reverts unless an address contains deployed code.
380	    /// @param account Address required to be a contract.
381	    function _requireContract(address account) private view {
382	        if (account.code.length == 0) revert NotContract(account);
383	    }
384	}
